script:
class Component extends DCLogic {
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
saveShared(k, v) { let r = false; try { r = parent.SONNA_STORE ? parent.SONNA_STORE.set(k, v) : false; } catch (e) {} if (!r) this._fail = true; return r; }
state = { msg: '', payment: null, deposits: [], simTopup: false, enabled: this.shared('topup', {}).enabled === true, pct: this.shared('topup', {}).pct || '5', min: this.shared('topup', {}).min || '0', cap: this.shared('topup', {}).cap || '', amount: '100000' };
mount() {
const api = parent.SONNA_API;
if (!api) return this.setState({ msg: 'Server API unavailable.' });
Promise.all([api('GET', '/api/session'), api('GET', '/api/admin/deposits')]).then((r) => {
if (r[0]._status !== 200 || r[1]._status !== 200) return this.setState({ msg: 'Could not load live SePay status or deposit history.' });
this.setState({ payment: r[0].payment || {}, simTopup: !!r[0].simTopup, deposits: r[1].deposits || [], msg: '' });
}).catch(() => this.setState({ msg: 'Connection to server failed.' }));
}
renderVals() {
const on = '#FF8A1F', off = '#A3ACC4';
const st = this.state;
const nav = [
{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' },
{ label: 'Quản lý acc', href: 'AdminAccounts.dc.html' },
{ label: 'Đơn hàng', href: 'AdminOrders.dc.html' },
{ label: 'Thanh toán', href: 'AdminPayments.dc.html', active: true },
{ label: 'Người dùng', href: 'AdminUsers.dc.html' },
{ label: 'Khuyến mãi', href: 'AdminPromos.dc.html' },
{ label: 'Nội dung website', href: 'AdminContent.dc.html' },
{ label: 'Báo cáo', href: '#bao-cao' },
{ label: 'Phân quyền', href: 'AdminRoles.dc.html' },
{ label: 'Nhật ký hoạt động', href: '#nhat-ky' }
].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));

const num = (s) => parseInt(String(s).replace(/\D/g, ''), 10) || 0;
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫';
const amt = num(st.amount);
const min = num(st.min);
const cap = num(st.cap);
const pct = parseFloat(String(st.pct).replace(',', '.')) || 0;
let bonus = 0;
let note = 'Khách nhận đúng số tiền đã nạp cộng thêm thưởng.';
if (!st.enabled) {
note = 'Khuyến mãi đang tắt: khách nhận đúng số tiền đã nạp (tỷ lệ 1:1).';
} else if (amt < min) {
note = 'Chưa đạt mức nạp tối thiểu để nhận thưởng: khách nhận đúng số tiền đã nạp.';
} else {
bonus = Math.round(amt * pct / 100);
if (cap > 0 && bonus > cap) { bonus = cap; note = 'Thưởng đã chạm mức tối đa mỗi lần.'; }
}
const calc = { amount: fmt(amt), bonus: fmt(bonus), total: fmt(amt + bonus), note };

const connectionStatus = st.simTopup ? 'WARNING: simulated wallet credits are enabled' : (st.payment && st.payment.ready ? 'SePay configured' : 'SePay not configured');
const deposits = (st.deposits || []).map((d) => ({ time: d.bankTime || d.time || '-', content: d.content || '-', user: d.username || 'Unmatched transfer', type: d.status === 'credited' ? 'Wallet credit' : d.status === 'ignored' ? 'Webhook ignored' : 'Unmatched transfer', amount: fmt(d.amount), bonus: Number(d.bonus) > 0 ? '+' + fmt(d.bonus) : '?', status: d.status === 'credited' ? 'Credited' : d.status === 'ignored' ? 'Ignored: ' + (d.reason || 'check payload') : 'Needs review', col: d.status === 'credited' ? '#43D9A0' : d.status === 'ignored' ? '#FF9AA5' : '#FFC24B', action: d.status === 'credited' ? 'View wallet' : 'Review' }));
const set = (k) => (e) => this.setState({ [k]: e.target.value });
return {
msgShow: st.msg !== '', msg: st.msg,
onFlash: () => this.setState({ msg: 'Store SePay credentials in data/payment.json, then restart the server.' }),
onTest: () => { const api = parent.SONNA_API; if (!api) return this.setState({ msg: 'Server API unavailable.' }); return Promise.all([api('GET', '/api/session'), api('GET', '/api/admin/deposits')]).then((r) => { if (r[0]._status !== 200 || r[1]._status !== 200) return this.setState({ msg: 'Could not reload server status or deposit history.' }); this.setState({ payment: r[0].payment || {}, simTopup: !!r[0].simTopup, deposits: r[1].deposits || [], msg: 'Server status reloaded. This does not test SePay webhook delivery.' }); }).catch(() => this.setState({ msg: 'Connection to server failed.' })); },
onSavePromo: () => { this._fail = false; this.saveShared('topup', { enabled: st.enabled, pct: st.pct, min: st.min, cap: st.cap }); this.setState({ msg: this._fail ? 'Không lưu được vào bộ nhớ trình duyệt.' : 'Đã lưu khuyến mãi nạp. Trang Cửa hàng sẽ áp dụng ngay.' }); },

nav, calc, connectionStatus, bankName: st.payment && (st.payment.bankName || st.payment.bankShortName) || "Not configured", accountNumber: st.payment && st.payment.accountNumber || "Not configured", accountName: st.payment && st.payment.accountName || "Not configured", webhookURL: (location.origin || "") + "/api/webhook/sepay", bankStatus: st.payment && st.payment.ready ? "Bank details and SePay authentication are configured on the server." : "Configure bank details and a SePay API key or HMAC secret in data/payment.json.",
pct: st.pct, min: st.min, cap: st.cap, amount: st.amount,
onPct: set('pct'), onMin: set('min'), onCap: set('cap'), onAmount: set('amount'),
onToggle: () => this.setState({ enabled: !this.state.enabled }),
promo: {
checked: st.enabled ? 'true' : 'false',
label: st.enabled ? 'Đang bật' : 'Đang tắt',
bg: st.enabled ? '#1F2538' : 'transparent',
fg: st.enabled ? '#43D9A0' : off
},
txs: deposits
};
}
}
